#!/usr/bin/env node
// =============================================================================
// check-deadlines.mjs: the deadline table has one source and two readers, and
// this is what keeps them the same.
//
//   scripts/data/deadlines.json          the source
//   dates-data.js + ics/*.ics            generated by gen-dates-ics.mjs
//                                        (freshness is that script's --check,
//                                        run here so one command covers all)
//   apps/guide/src/content/deadlines.ts  the Field Guide's hand mirror
//
// Fails when the mirror's set of ids differs from the JSON's, when a mirrored
// row's kind, offsetDays, monthsAhead, tag or source disagrees, or when the
// mirror's verified date is older than the JSON's. Titles and details are
// compared too, because the app prints them to a buyer and a corrected detail
// that reaches the site but not the app is exactly the drift this exists to
// catch. Part of `npm --prefix scripts run check`.
// =============================================================================

import { readFileSync, existsSync } from "node:fs";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");
const errors = [];

// 1. Generated mirrors fresh.
const gen = spawnSync(process.execPath, [path.join(__dirname, "gen-dates-ics.mjs"), "--check"], { encoding: "utf8" });
if (gen.status !== 0) errors.push((gen.stderr || gen.stdout || "gen-dates-ics --check failed").trim());

// 2. The PWA mirror.
const json = JSON.parse(readFileSync(path.join(__dirname, "data", "deadlines.json"), "utf8"));
const mirrorPath = path.join(ROOT, "apps", "guide", "src", "content", "deadlines.ts");
if (!existsSync(mirrorPath)) {
  errors.push(`apps/guide/src/content/deadlines.ts is missing; the Field Guide has no copy of the deadline table`);
} else {
  const ts = readFileSync(mirrorPath, "utf8");
  const verified = /(?:verified|VERIFIED)\s*[:=]\s*['"](\d{4}-\d{2}-\d{2})['"]/.exec(ts);
  if (!verified) errors.push("deadlines.ts: no `verified: 'YYYY-MM-DD'` found");
  else if (verified[1] < json.verified) errors.push(`deadlines.ts verified ${verified[1]} is older than deadlines.json ${json.verified}`);

  // Pull each object literal by its id and compare the fields the app reads.
  const ids = [...ts.matchAll(/\bid:\s*['"]([a-z0-9-]+)['"]/g)].map((m) => m[1]);
  const jsonIds = json.items.map((it) => it.id);
  for (const id of jsonIds) if (!ids.includes(id)) errors.push(`deadlines.ts is missing row "${id}"`);
  for (const id of ids) if (!jsonIds.includes(id)) errors.push(`deadlines.ts carries "${id}", which deadlines.json does not`);

  // Read `name: <number>` or `name: '<string>'` from an object literal,
  // allowing a line break after the colon (prettier wraps long strings) and
  // either quote style with backslash escapes inside.
  const field = (block, name) => {
    const m = new RegExp(`\\b${name}:\\s*`).exec(block);
    if (!m) return undefined;
    let i = m.index + m[0].length;
    const q = block[i];
    if (q !== "'" && q !== '"' && q !== "`") {
      const n = /^-?\d+/.exec(block.slice(i));
      return n ? Number(n[0]) : undefined;
    }
    let out = "";
    for (i += 1; i < block.length; i++) {
      const ch = block[i];
      if (ch === "\\") { out += block[i + 1]; i++; continue; }
      if (ch === q) return out;
      out += ch;
    }
    return undefined;
  };
  for (const it of json.items) {
    const at = ts.indexOf(`id: '${it.id}'`) >= 0 ? ts.indexOf(`id: '${it.id}'`) : ts.indexOf(`id: "${it.id}"`);
    if (at < 0) continue;
    // The row runs from its id to the next row's id (or the array's end).
    const next = ts.slice(at + 10).search(/\bid:\s*['"]/);
    const block = ts.slice(at, next < 0 ? ts.length : at + 10 + next);
    const compare = ["kind", "tag", "source", "title", "detail", "time", "confidence"];
    if (it.kind === "relative") compare.push("offsetDays");
    if (it.kind === "release-15th") compare.push("monthsAhead");
    if (it.kind === "rule") compare.push("rule");
    for (const f of compare) {
      const got = field(block, f);
      if (got === undefined) { errors.push(`deadlines.ts ${it.id}: no ${f}`); continue; }
      if (String(got) !== String(it[f])) errors.push(`deadlines.ts ${it.id}.${f} differs from deadlines.json\n    ts:   ${String(got).slice(0, 90)}\n    json: ${String(it[f]).slice(0, 90)}`);
    }
  }
}

if (errors.length) {
  console.error(`check-deadlines: ${errors.length} problem(s)`);
  for (const e of errors) console.error("  " + e);
  process.exit(1);
}
console.log(`check-deadlines: ${json.items.length} rows agree across the JSON, the generated mirrors and the Field Guide`);
